// Handler creates http.Handler with routing matching OpenAPI spec.
func Handler(si ServerInterface) http.Handler {
	return HandlerWithOptions(si, StdHTTPServerOptions{})
}

// ServeMux is an abstraction of [http.ServeMux].
type ServeMux interface {
	HandleFunc(pattern string, handler func(http.ResponseWriter, *http.Request))
	http.Handler
}

type StdHTTPServerOptions struct {
	BaseURL          string
	BaseRouter       ServeMux
	Middlewares      []MiddlewareFunc
	ErrorHandlerFunc func(w http.ResponseWriter, r *http.Request, err error)
}

// HandlerFromMux creates http.Handler with routing matching OpenAPI spec based on the provided mux.
func HandlerFromMux(si ServerInterface, m ServeMux) http.Handler {
	return HandlerWithOptions(si, StdHTTPServerOptions{
		BaseRouter: m,
	})
}

func HandlerFromMuxWithBaseURL(si ServerInterface, m ServeMux, baseURL string) http.Handler {
	return HandlerWithOptions(si, StdHTTPServerOptions{
		BaseURL:    baseURL,
		BaseRouter: m,
	})
}

// HandlerWithOptions creates http.Handler with additional options
func HandlerWithOptions(si ServerInterface, options StdHTTPServerOptions) http.Handler {
	m := options.BaseRouter

	if m == nil {
		m = http.NewServeMux()
	}
	if options.ErrorHandlerFunc == nil {
		options.ErrorHandlerFunc = func(w http.ResponseWriter, r *http.Request, err error) {
			http.Error(w, err.Error(), http.StatusBadRequest)
		}
	}

	wrapper := ServerInterfaceWrapper{
		Handler:            si,
		HandlerMiddlewares: options.Middlewares,
		ErrorHandlerFunc:   options.ErrorHandlerFunc,
	}

	m.HandleFunc(http.MethodGet+" "+options.BaseURL+"/api/v1/version", wrapper.GetVersion)
	m.HandleFunc(http.MethodGet+" "+options.BaseURL+"/api/v1/servers", wrapper.ListServers)
	m.HandleFunc(http.MethodPost+" "+options.BaseURL+"/api/v1/servers", wrapper.CreateServer)
	m.HandleFunc(http.MethodDelete+" "+options.BaseURL+"/api/v1/servers/{server_id}", wrapper.DeleteServer)
	m.HandleFunc(http.MethodGet+" "+options.BaseURL+"/api/v1/servers/{server_id}", wrapper.GetServer)
	m.HandleFunc(http.MethodPatch+" "+options.BaseURL+"/api/v1/servers/{server_id}", wrapper.UpdateServer)
	m.HandleFunc(http.MethodPost+" "+options.BaseURL+"/api/v1/servers/{server_id}/check", wrapper.CheckServer)
	m.HandleFunc(http.MethodPost+" "+options.BaseURL+"/api/v1/servers/{server_id}/host-key", wrapper.TrustHostKey)
	m.HandleFunc(http.MethodPost+" "+options.BaseURL+"/api/v1/servers/{server_id}/discover", wrapper.DiscoverProjects)
	m.HandleFunc(http.MethodGet+" "+options.BaseURL+"/api/v1/config", wrapper.ExportConfig)
	m.HandleFunc(http.MethodPost+" "+options.BaseURL+"/api/v1/config", wrapper.ImportConfig)
	m.HandleFunc(http.MethodGet+" "+options.BaseURL+"/api/v1/projects", wrapper.ListProjects)
	m.HandleFunc(http.MethodPost+" "+options.BaseURL+"/api/v1/projects", wrapper.CreateProject)
	m.HandleFunc(http.MethodDelete+" "+options.BaseURL+"/api/v1/projects/{project_id}", wrapper.DeleteProject)
	m.HandleFunc(http.MethodGet+" "+options.BaseURL+"/api/v1/projects/{project_id}", wrapper.GetProject)
	m.HandleFunc(http.MethodPatch+" "+options.BaseURL+"/api/v1/projects/{project_id}", wrapper.UpdateProject)
	m.HandleFunc(http.MethodGet+" "+options.BaseURL+"/api/v1/projects/{project_id}/debugger", wrapper.GetDebuggerState)
	m.HandleFunc(http.MethodPut+" "+options.BaseURL+"/api/v1/projects/{project_id}/debugger", wrapper.SetDebuggerState)
	m.HandleFunc(http.MethodDelete+" "+options.BaseURL+"/api/v1/projects/{project_id}/logs", wrapper.ClearProjectLogs)
	m.HandleFunc(http.MethodGet+" "+options.BaseURL+"/api/v1/requests", wrapper.ListRequests)
	m.HandleFunc(http.MethodDelete+" "+options.BaseURL+"/api/v1/requests/{request_id}", wrapper.DeleteRequest)
	m.HandleFunc(http.MethodGet+" "+options.BaseURL+"/api/v1/requests/{request_id}", wrapper.GetRequest)
	m.HandleFunc(http.MethodGet+" "+options.BaseURL+"/api/v1/requests/{request_id}/messages", wrapper.ListMessages)
	m.HandleFunc(http.MethodGet+" "+options.BaseURL+"/api/v1/messages/{message_id}", wrapper.GetMessage)
	m.HandleFunc(http.MethodGet+" "+options.BaseURL+"/api/v1/messages/{message_id}/source", wrapper.GetMessageSource)
	m.HandleFunc(http.MethodGet+" "+options.BaseURL+"/api/v1/stream", wrapper.StreamEvents)
	m.HandleFunc(http.MethodGet+" "+options.BaseURL+"/api/v1/desktop/settings", wrapper.GetDesktopSettings)
	m.HandleFunc(http.MethodPut+" "+options.BaseURL+"/api/v1/desktop/settings", wrapper.UpdateDesktopSettings)
	m.HandleFunc(http.MethodGet+" "+options.BaseURL+"/api/v1/updates", wrapper.GetUpdates)
	m.HandleFunc(http.MethodGet+" "+options.BaseURL+"/api/v1/settings", wrapper.GetSettings)
	m.HandleFunc(http.MethodPut+" "+options.BaseURL+"/api/v1/settings", wrapper.UpdateSettings)

	return m
}

